package com.example.workout.workout.controller;
import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.when; import com.example.workout.generated.model.*; import com.example.workout.workout.model.Workout; import com.example.workout.workout.service.WorkoutService; import java.time.*; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class) class WorkoutControllerTest { @Mock private WorkoutService service; @Test void create_returns_201_ok(){var controller=new WorkoutController(service);var request=new WorkoutCreateRequest();request.setWorkoutDate(LocalDate.of(2026,9,20));request.setWorkoutType(WorkoutType.LONG_RUN);request.setCompleted(true);request.setSource(WorkoutSource.MANUAL);var created=Workout.builder().withId(1L).withWorkoutDate(request.getWorkoutDate()).withWorkoutType(com.example.workout.workout.model.WorkoutType.LONG_RUN).withCompleted(true).withSource(com.example.workout.workout.model.WorkoutSource.MANUAL).withCreatedAt(OffsetDateTime.now()).withUpdatedAt(OffsetDateTime.now()).build();when(service.create(org.mockito.ArgumentMatchers.any(Workout.class))).thenReturn(created);var response=controller.createWorkout(request);assertThat(response.getStatusCode().value()).isEqualTo(201);assertThat(response.getBody()).isNotNull();assertThat(response.getBody().getId()).isEqualTo(1L);} }
